<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { api } from '../api';
import { emptyCatalogue, standardCardFields, type AssetCategory, type CardType, type CardField } from '../catalogue';
import AppIcon from './AppIcon.vue';

type Tab = 'categories' | 'codes' | 'cards';
const props = defineProps<{ initialTab?: Tab }>();
const emit = defineEmits<{ changed: []; success: [message: string] }>();
const tab = ref<Tab>(props.initialTab || 'categories');
const catalogue = ref(emptyCatalogue()); const loading = ref(true); const error = ref(''); const busy = ref(false); const search = ref('');
const dialog = ref<HTMLDialogElement | null>(null); const editing = ref<'category' | 'card' | null>(null); const dialogError = ref('');
const categoryForm = reactive({ id: null as number | null, code: '', name: '', parent_id: null as number | null, card_type_id: 0, active: 1, remark: '', expectedVersion: 0 });
const cardForm = reactive({ id: null as number | null, name: '', active: 1, fields: [] as CardField[], expectedVersion: 0 });
const prefix = ref(''); const ruleForm = reactive({ digits: 4, next_number: 1, expectedVersion: 0 }); const rulePreview = ref(''); const ruleBusy = ref(false);
const roots = computed(() => catalogue.value.categories.filter(c => !c.parent_id));
const orderedCategories = computed(() => roots.value.flatMap(c => [c, ...catalogue.value.categories.filter(child => child.parent_id === c.id)]).filter(c => `${c.path} ${c.code} ${c.card_name}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const currentRule = computed(() => catalogue.value.rules.find(r => r.prefix === prefix.value));
const sample = computed(() => prefix.value ? `${prefix.value}-${String(ruleForm.next_number || 1).padStart(ruleForm.digits || 1, '0')}` : '请选择分类前缀');
const availableFields = computed(() => standardCardFields.filter(f => !cardForm.fields.some(v => v.key === f.key)));
const standardToAdd = ref('');
let disposed = false;
watch(() => props.initialTab, value => { if (value) tab.value = value; });
watch(prefix, () => selectRule());
function selectRule() { const r = currentRule.value; if (r) Object.assign(ruleForm, { digits: r.digits, next_number: r.next_number, expectedVersion: r.version }); rulePreview.value = ''; }
async function load() { loading.value = true; error.value = ''; try { const result = await api.catalogue(); if (disposed) return; catalogue.value = result; if (!prefix.value) prefix.value = result.rules[0]?.prefix || ''; selectRule(); } catch (e) { error.value = e instanceof Error ? e.message : '设置加载失败'; } finally { loading.value = false; } }
async function openCategory(c?: AssetCategory, parent?: number) {
  Object.assign(categoryForm, { id: c?.id || null, code: c?.code || '', name: c?.name || '', parent_id: c?.parent_id || parent || null, card_type_id: c?.card_type_id || catalogue.value.cards.find(v => v.active)?.id || 0, active: c?.active ?? 1, remark: c?.remark || '', expectedVersion: c?.version || 0 });
  editing.value = 'category'; dialogError.value = ''; await nextTick(); dialog.value?.showModal();
}
async function openCard(c?: CardType) { Object.assign(cardForm, { id: c?.id || null, name: c?.name || '', active: c?.active ?? 1, expectedVersion: c?.version || 0, fields: structuredClone(c ? JSON.parse(JSON.stringify(c.fields)) : standardCardFields.filter(f => ['model', 'serial_number', 'remark'].includes(f.key))) }); standardToAdd.value = ''; editing.value = 'card'; dialogError.value = ''; await nextTick(); dialog.value?.showModal(); }
function close(event?: Event) { if (busy.value) { event?.preventDefault(); return; } dialog.value?.close(); editing.value = null; }
async function save() { if (busy.value) return; busy.value = true; dialogError.value = ''; try { if (editing.value === 'category') await api.saveCategory(categoryForm.id, { ...categoryForm }); else await api.saveCard(cardForm.id, { ...cardForm, fields: cardForm.fields.map(f => ({ ...f, options: f.type === 'select' ? f.options || [] : undefined })) }); busy.value = false; close(); await load(); emit('changed'); emit('success', '设置已保存'); } catch (e) { dialogError.value = e instanceof Error ? e.message : '保存失败'; } finally { busy.value = false; } }
async function saveRule() { if (!prefix.value || ruleBusy.value) return; ruleBusy.value = true; error.value = ''; try { const result = await api.saveCodeRule({ prefix: prefix.value, ...ruleForm }); await load(); rulePreview.value = result.preview; emit('success', '编码规则已保存'); } catch (e) { error.value = e instanceof Error ? e.message : '编码保存失败'; } finally { ruleBusy.value = false; } }
function addStandard() { const field = standardCardFields.find(f => f.key === standardToAdd.value); if (field && !cardForm.fields.some(f => f.key === field.key)) cardForm.fields.push({ ...field }); standardToAdd.value = ''; }
function addCustom() { cardForm.fields.push({ key: `custom_f${crypto.randomUUID().replaceAll('-', '').slice(0, 12)}`, label: '新字段', type: 'text', required: false }); }
function optionsChanged(field: CardField, event: Event) { field.options = (event.target as HTMLTextAreaElement).value.split('\n').map(v => v.trim()).filter(Boolean); }
onMounted(load); onBeforeUnmount(() => { disposed = true; dialog.value?.close(); });
</script>

<template>
  <div class="catalogue-settings">
    <nav class="catalogue-tabs" aria-label="资产基础设置"><button v-for="item in [{ id: 'categories', label: '资产分类', icon: 'grid' }, { id: 'codes', label: '编码规则', icon: 'code' }, { id: 'cards', label: '资产卡片', icon: 'card' }]" :key="item.id" :class="{ active: tab === item.id }" :aria-current="tab === item.id ? 'page' : undefined" @click="tab = item.id as Tab"><AppIcon :name="item.icon" />{{ item.label }}</button></nav>
    <p v-if="error" class="scan-error" role="alert">{{ error }}<button class="text-button" @click="load">重新加载</button></p>
    <div v-if="loading" class="panel empty-history" role="status">正在加载资产设置…</div>
    <article v-else-if="tab === 'categories'" class="panel catalogue-panel">
      <header class="panel-header"><div><h2>资产分类</h2><p>按类别管理资产，为每个分类绑定卡片和编码前缀。</p></div><button class="primary-button icon-text" @click="openCategory()"><AppIcon name="plus" :size="17" />新增分类</button></header>
      <label class="catalogue-search"><AppIcon name="search" /><input v-model="search" type="search" aria-label="搜索资产分类" placeholder="搜索分类、编码或卡片" /></label>
      <div class="catalogue-list"><div class="catalogue-list-head"><span>分类名称 / 编码</span><span>资产卡片</span><span>资产数</span><span>操作</span></div><div v-for="c in orderedCategories" :key="c.id" class="catalogue-category-row" :class="{ child: c.parent_id, inactive: !c.active }"><div class="category-name"><AppIcon :name="c.parent_id ? 'box' : 'grid'" :size="18" /><span><strong>{{ c.name }}</strong><small>{{ c.code }}<em v-if="!c.active">已停用</em></small></span></div><span class="category-card">{{ c.card_name }}</span><span class="category-count">{{ c.assets_count }} 件</span><div class="category-actions"><button class="text-button" :aria-label="`编辑${c.name}`" @click="openCategory(c)">编辑</button><button v-if="!c.parent_id" class="text-button" :aria-label="`在${c.name}下新增分类`" @click="openCategory(undefined, c.id)">新增下级</button></div></div><p v-if="!orderedCategories.length" class="empty-history">没有匹配的资产分类</p></div>
    </article>
    <article v-else-if="tab === 'codes'" class="panel code-settings-panel">
      <header class="panel-header"><div><h2>资产编码规则</h2><p>分类前缀 + 流水号，新增时自动编号。</p></div></header>
      <div class="code-settings-layout"><form @submit.prevent="saveRule"><div class="form-grid"><label class="field field-wide"><span>分类前缀 *</span><select v-model="prefix" required><option v-for="r in catalogue.rules" :key="r.id" :value="r.prefix">{{ r.prefix }} · {{ catalogue.categories.find(c => c.code === r.prefix)?.name || '保留规则' }}</option></select></label><label class="field"><span>流水号最少位数 *</span><input v-model.number="ruleForm.digits" type="number" min="1" max="12" required /></label><label class="field"><span>下一个流水号 *</span><input v-model.number="ruleForm.next_number" type="number" min="1" max="999999999999" required /></label></div><p class="catalogue-help">不足位数时补零；超过位数时自动增长。保存时会核对现存最大号，已分配的流水号不能回退。</p><button class="primary-button" :disabled="ruleBusy || !prefix">{{ ruleBusy ? '保存中…' : '保存编码规则' }}</button></form><aside class="code-example"><span>编码示例</span><strong>{{ sample }}</strong><div><span>{{ prefix || '分类前缀' }}</span><i>+</i><span>流水号</span></div><p>已有资产编码保持原样，已贴的二维码继续有效。</p><p v-if="rulePreview" role="status">当前下一个可用编码：{{ rulePreview }}</p></aside></div>
    </article>
    <article v-else class="panel catalogue-panel"><header class="panel-header"><div><h2>资产卡片类型</h2><p>配置不同类别需要填写的资料，也可以增加自定义字段。</p></div><button class="primary-button icon-text" @click="openCard()"><AppIcon name="plus" :size="17" />新增卡片</button></header><div class="card-template-grid"><button v-for="card in catalogue.cards" :key="card.id" class="card-template" @click="openCard(card)"><div><span class="template-icon"><AppIcon name="card" :size="26" /></span><span :class="['template-state', { inactive: !card.active }]">{{ card.active ? '已启用' : '已停用' }}</span></div><h3>{{ card.name }}</h3><p>{{ card.fields.length }} 个资料字段 · {{ card.fields.filter(f => f.required).length }} 个必填</p><div class="template-fields"><span v-for="field in card.fields.slice(0, 4)" :key="field.key">{{ field.label }}</span><span v-if="card.fields.length > 4">+{{ card.fields.length - 4 }}</span></div><span class="template-edit">配置字段<AppIcon name="chevron" :size="15" /></span></button></div></article>

    <dialog v-if="editing" ref="dialog" class="catalogue-edit-dialog" aria-labelledby="catalogue-edit-title" @cancel="close"><form @submit.prevent="save"><header class="catalogue-dialog-heading"><div><span class="eyebrow">资产基础设置</span><h2 id="catalogue-edit-title">{{ editing === 'category' ? `${categoryForm.id ? '编辑' : '新增'}资产分类` : `${cardForm.id ? '编辑' : '新增'}资产卡片` }}</h2></div><button type="button" class="icon-button" aria-label="关闭设置表单" :disabled="busy" @click="close()"><AppIcon name="close" /></button></header><div class="catalogue-edit-scroll"><p v-if="dialogError" class="scan-error" role="alert">{{ dialogError }}</p><fieldset :disabled="busy" class="catalogue-fieldset"><div v-if="editing === 'category'" class="form-grid"><label class="field"><span>分类名称 *</span><input v-model="categoryForm.name" maxlength="100" required /></label><label class="field"><span>分类编码 / 新资产前缀 *</span><input v-model="categoryForm.code" maxlength="32" pattern="[A-Z0-9]+" required placeholder="例如：CSJ" /></label><label class="field"><span>上级分类</span><select v-model="categoryForm.parent_id"><option :value="null">一级分类</option><option v-for="root in roots.filter(r => r.id !== categoryForm.id)" :key="root.id" :value="root.id">{{ root.name }}</option></select></label><label class="field"><span>绑定资产卡片 *</span><select v-model="categoryForm.card_type_id" required><option v-for="card in catalogue.cards.filter(c => c.active)" :key="card.id" :value="card.id">{{ card.name }}</option></select></label><label class="field"><span>状态</span><select v-model="categoryForm.active"><option :value="1">启用</option><option :value="0">停用</option></select></label><label class="field field-wide"><span>备注</span><textarea v-model="categoryForm.remark" rows="3" maxlength="1000" /></label><p class="catalogue-help field-wide">修改分类名称会同步更新台账中的分类。修改编码前缀只影响后续新增资产。</p></div>
      <template v-else><div class="form-grid"><label class="field"><span>卡片名称 *</span><input v-model="cardForm.name" required maxlength="200" /></label><label class="field"><span>状态</span><select v-model="cardForm.active"><option :value="1">启用</option><option :value="0">停用</option></select></label></div><p class="catalogue-help">名称、分类、编码、公司及使用信息为固定字段。以下资料字段用于补充不同类型资产。</p><div class="card-field-list"><div v-for="(field, index) in cardForm.fields" :key="field.key" class="card-field-row"><label class="field"><span>字段名称</span><input v-model="field.label" required maxlength="60" /></label><label class="field"><span>字段类型</span><select v-model="field.type"><option value="text" :disabled="field.type === 'number' && !field.key.startsWith('custom_')">文本</option><option v-if="field.key.startsWith('custom_') || ['amount_taxed','amount_untaxed','tax_amount'].includes(field.key)" value="number">数字</option><option v-if="field.key.startsWith('custom_')" value="date">日期</option><option v-if="!['amount_taxed','amount_untaxed','tax_amount'].includes(field.key)" value="select">选项</option></select></label><label class="checkbox-label"><input v-model="field.required" type="checkbox" />必填</label><button type="button" class="icon-button" :aria-label="`移除字段${field.label}`" @click="cardForm.fields.splice(index,1)"><AppIcon name="close" :size="16" /></button><label v-if="field.type === 'select'" class="field field-wide"><span>选项（每行一个）</span><textarea :value="field.options?.join('\n') || ''" rows="3" required @change="optionsChanged(field,$event)" /></label></div></div><div class="card-add-field"><label class="field"><span class="sr-only">添加标准字段</span><select v-model="standardToAdd"><option value="">选择标准字段</option><option v-for="field in availableFields" :key="field.key" :value="field.key">{{ field.label }}</option></select></label><button type="button" class="secondary-button" :disabled="!standardToAdd || cardForm.fields.length >= 40" @click="addStandard">添加字段</button><button type="button" class="secondary-button" :disabled="cardForm.fields.length >= 40" @click="addCustom">添加自定义字段</button></div></template></fieldset></div><footer class="asset-form-footer"><p>保存后，新建和编辑资产使用最新配置。</p><div class="form-actions"><button type="button" class="secondary-button" :disabled="busy" @click="close()">取消</button><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存设置' }}</button></div></footer></form></dialog>
  </div>
</template>
